CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE policy_source (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,name text NOT NULL,source_class text NOT NULL,owner_ref text NOT NULL,status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,name));
CREATE TABLE policy_version_reference (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,policy_source_id uuid NOT NULL,version text NOT NULL,checksum text NOT NULL,effective_at timestamptz,retired_at timestamptz,authority_rank integer NOT NULL,validated_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,policy_source_id,version),FOREIGN KEY(policy_source_id,tenant_id) REFERENCES policy_source(id,tenant_id));
CREATE TABLE policy_applicability_rule (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,policy_version_id uuid NOT NULL,criteria jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',approved_by uuid,approved_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(policy_version_id,tenant_id) REFERENCES policy_version_reference(id,tenant_id));
CREATE TABLE policy_precedence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,higher_version_id uuid NOT NULL,lower_version_id uuid NOT NULL,scope jsonb NOT NULL,rationale text NOT NULL,status text NOT NULL DEFAULT 'proposed',approved_by uuid,approved_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,higher_version_id,lower_version_id),FOREIGN KEY(higher_version_id,tenant_id) REFERENCES policy_version_reference(id,tenant_id),FOREIGN KEY(lower_version_id,tenant_id) REFERENCES policy_version_reference(id,tenant_id));
CREATE TABLE governance_assessment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,subject_type text NOT NULL,subject_id text NOT NULL,status text NOT NULL DEFAULT 'requested',result text,confidence numeric CHECK(confidence BETWEEN 0 AND 1),requested_by uuid NOT NULL,issued_by uuid,issued_at timestamptz,idempotency_key text NOT NULL,UNIQUE(id,tenant_id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE assessment_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,assessment_id uuid NOT NULL,policy_version_id uuid NOT NULL,locator text NOT NULL,excerpt text,lineage jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending',UNIQUE(id,tenant_id),UNIQUE(tenant_id,assessment_id,policy_version_id,locator),FOREIGN KEY(assessment_id,tenant_id) REFERENCES governance_assessment(id,tenant_id),FOREIGN KEY(policy_version_id,tenant_id) REFERENCES policy_version_reference(id,tenant_id));
CREATE TABLE compliance_finding (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,assessment_id uuid NOT NULL,finding_type text NOT NULL,severity text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open',reviewed_by uuid,reviewed_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(assessment_id,tenant_id) REFERENCES governance_assessment(id,tenant_id));
CREATE TABLE policy_conflict (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,assessment_id uuid NOT NULL,left_version_id uuid NOT NULL,right_version_id uuid NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open',disposition text,decided_by uuid,decided_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(assessment_id,tenant_id) REFERENCES governance_assessment(id,tenant_id),FOREIGN KEY(left_version_id,tenant_id) REFERENCES policy_version_reference(id,tenant_id),FOREIGN KEY(right_version_id,tenant_id) REFERENCES policy_version_reference(id,tenant_id));
CREATE TABLE exception_request (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,assessment_id uuid NOT NULL,requested_by uuid NOT NULL,justification text NOT NULL,scope jsonb NOT NULL,risk jsonb NOT NULL,expires_at timestamptz,status text NOT NULL DEFAULT 'requested',UNIQUE(id,tenant_id),FOREIGN KEY(assessment_id,tenant_id) REFERENCES governance_assessment(id,tenant_id));
CREATE TABLE exception_decision (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,exception_request_id uuid NOT NULL,decision text NOT NULL CHECK(decision IN('approved','rejected','returned')),decided_by uuid NOT NULL,rationale text NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,exception_request_id),FOREIGN KEY(exception_request_id,tenant_id) REFERENCES exception_request(id,tenant_id));
CREATE TABLE governance_recommendation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,assessment_id uuid NOT NULL,title text NOT NULL,recommendation text NOT NULL,evidence jsonb NOT NULL,impact jsonb NOT NULL,confidence numeric CHECK(confidence BETWEEN 0 AND 1),status text NOT NULL DEFAULT 'draft',decided_by uuid,decided_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(assessment_id,tenant_id) REFERENCES governance_assessment(id,tenant_id));
CREATE TABLE governance_briefing (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,title text NOT NULL,version integer NOT NULL,content jsonb NOT NULL,citations jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',issued_by uuid,issued_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,title,version));
CREATE TABLE governance_advisory_request (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,assessment_id uuid,advisory_type text NOT NULL CHECK(advisory_type IN('nova','pops')),request_text text NOT NULL,response jsonb,status text NOT NULL DEFAULT 'requested',requested_by uuid NOT NULL,completed_at timestamptz,idempotency_key text NOT NULL,UNIQUE(id,tenant_id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(assessment_id,tenant_id) REFERENCES governance_assessment(id,tenant_id));
CREATE TABLE governance_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,UNIQUE(id,tenant_id));
CREATE INDEX idx_policy_effective ON policy_version_reference(tenant_id,effective_at,retired_at); CREATE INDEX idx_assessment_status ON governance_assessment(tenant_id,status); CREATE INDEX idx_finding_open ON compliance_finding(tenant_id,status,severity); CREATE INDEX idx_outbox_pending ON governance_outbox(status,created_at) WHERE status='pending';
CREATE OR REPLACE FUNCTION prevent_governance_self_approval() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE requester uuid; BEGIN IF TG_TABLE_NAME='exception_decision' THEN SELECT requested_by INTO requester FROM exception_request WHERE id=NEW.exception_request_id AND tenant_id=NEW.tenant_id; IF requester=NEW.decided_by THEN RAISE EXCEPTION 'self-approval prohibited'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_exception_self_approval BEFORE INSERT ON exception_decision FOR EACH ROW EXECUTE FUNCTION prevent_governance_self_approval();
CREATE OR REPLACE FUNCTION protect_governance_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (TG_TABLE_NAME='policy_source' AND OLD.status='active') OR (TG_TABLE_NAME='policy_version_reference' AND OLD.validated_at IS NOT NULL) OR (TG_TABLE_NAME='policy_applicability_rule' AND OLD.status='active') OR (TG_TABLE_NAME='policy_precedence' AND OLD.status='approved') OR (TG_TABLE_NAME='governance_assessment' AND OLD.status='issued') OR (TG_TABLE_NAME='assessment_evidence' AND OLD.status='validated') OR (TG_TABLE_NAME='compliance_finding' AND OLD.status='reviewed') OR (TG_TABLE_NAME='policy_conflict' AND OLD.status='disposed') OR (TG_TABLE_NAME='exception_request' AND OLD.status IN('approved','rejected')) OR TG_TABLE_NAME='exception_decision' OR (TG_TABLE_NAME='governance_recommendation' AND OLD.status IN('approved','rejected')) OR (TG_TABLE_NAME='governance_briefing' AND OLD.status='issued') OR (TG_TABLE_NAME='governance_advisory_request' AND OLD.status='completed') THEN RAISE EXCEPTION 'governed record is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_policy_source_immutable BEFORE UPDATE OR DELETE ON policy_source FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_policy_version_immutable BEFORE UPDATE OR DELETE ON policy_version_reference FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_applicability_immutable BEFORE UPDATE OR DELETE ON policy_applicability_rule FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_precedence_immutable BEFORE UPDATE OR DELETE ON policy_precedence FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_assessment_immutable BEFORE UPDATE OR DELETE ON governance_assessment FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_evidence_immutable BEFORE UPDATE OR DELETE ON assessment_evidence FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_finding_immutable BEFORE UPDATE OR DELETE ON compliance_finding FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_conflict_immutable BEFORE UPDATE OR DELETE ON policy_conflict FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_exception_immutable BEFORE UPDATE OR DELETE ON exception_request FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_exception_decision_immutable BEFORE UPDATE OR DELETE ON exception_decision FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_recommendation_immutable BEFORE UPDATE OR DELETE ON governance_recommendation FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_briefing_immutable BEFORE UPDATE OR DELETE ON governance_briefing FOR EACH ROW EXECUTE FUNCTION protect_governance_record(); CREATE TRIGGER trg_advisory_immutable BEFORE UPDATE OR DELETE ON governance_advisory_request FOR EACH ROW EXECUTE FUNCTION protect_governance_record();
ALTER TABLE policy_source ENABLE ROW LEVEL SECURITY; ALTER TABLE policy_version_reference ENABLE ROW LEVEL SECURITY; ALTER TABLE policy_applicability_rule ENABLE ROW LEVEL SECURITY; ALTER TABLE policy_precedence ENABLE ROW LEVEL SECURITY; ALTER TABLE governance_assessment ENABLE ROW LEVEL SECURITY; ALTER TABLE assessment_evidence ENABLE ROW LEVEL SECURITY; ALTER TABLE compliance_finding ENABLE ROW LEVEL SECURITY; ALTER TABLE policy_conflict ENABLE ROW LEVEL SECURITY; ALTER TABLE exception_request ENABLE ROW LEVEL SECURITY; ALTER TABLE exception_decision ENABLE ROW LEVEL SECURITY; ALTER TABLE governance_recommendation ENABLE ROW LEVEL SECURITY; ALTER TABLE governance_briefing ENABLE ROW LEVEL SECURITY; ALTER TABLE governance_advisory_request ENABLE ROW LEVEL SECURITY; ALTER TABLE governance_outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY policy_source_tenant ON policy_source USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY policy_version_tenant ON policy_version_reference USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY applicability_tenant ON policy_applicability_rule USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY precedence_tenant ON policy_precedence USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY assessment_tenant ON governance_assessment USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY evidence_tenant ON assessment_evidence USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY finding_tenant ON compliance_finding USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY conflict_tenant ON policy_conflict USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY exception_tenant ON exception_request USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY exception_decision_tenant ON exception_decision USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY recommendation_tenant ON governance_recommendation USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY briefing_tenant ON governance_briefing USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY advisory_tenant ON governance_advisory_request USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY outbox_tenant ON governance_outbox USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid);
